import React from "react";

export function RangeSlider() {
  return (
    <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md">
  <h2 className="text-2xl font-bold mb-4">Range Slider</h2>
  <div className="mb-4">
    <label for="price-range" className="block text-gray-700 font-bold mb-2">Price Range</label>
    <input type="range" id="price-range" className="w-full accent-indigo-600" min="0" max="1000" value="500" />
  </div>
  <div className="flex justify-between text-gray-500">
    <span id="minPrice">$0</span>
    <span id="maxPrice">$1000</span>
  </div>
</div>
  );
}
